#!/usr/bin/env bash\n\nset -euo pipefail\n\n# --- Configuration ---\n# List of post‑apocalyptic quotes.  Feel free to add more!\nquotes=(\n  "The ash settles, but the code lives on."\n  "When the servers fall, the logs shall rise again."\n  "In the wasteland of bugs, only the brave commit."\n  "May your CI be green and your pipelines never crash."\n  "Even in a broken build, hope persists."\n)\n\n# Choose a quote.  For deterministic testing we allow overriding via QUOTE_INDEX env var.\nif [[ -n "${QUOTE_INDEX-}" ]]; then\n  index=$QUOTE_INDEX\nelse\n  # Bash's $RANDOM is pseudo‑random; modulo the number of quotes.\n  index=$((RANDOM % ${#quotes[@]}))\nfi\nselected_quote="${quotes[$index]}"\n\n# Extract needed GitHub context variables.\nif [[ -z "${GITHUB_EVENT_PATH-}" ]]; then\n  echo "Error: GITHUB_EVENT_PATH is not set" >&2\n  exit 1\nfi\n\n# Parse the JSON event payload to get the issue number and repository.\n# We avoid jq to keep dependencies minimal; use built‑in bash string processing.\n# The payload is small, so a simple grep/awk approach works for our limited fields.\n\n# Read the whole payload.\npayload=$(cat "$GITHUB_EVENT_PATH")\n\n# Extract issue number.\nissue_number=$(echo "$payload" | grep -o '"number": *[0-9]\+' | head -n1 | grep -o '[0-9]\+')\n\n# Extract repository owner and name (format: owner/repo).\nrepo="$GITHUB_REPOSITORY"\n\n# Build the API URL.\napi_url="https://api.github.com/repos/$repo/issues/$issue_number/comments"\n\n# Prepare JSON body.\njson_body=$(printf '{"body": "%s"}' "${selected_quote//"/\\\"}")\n\n# Post the comment using curl.\n# The token is passed via Authorization header.\ncurl -s -X POST \n  -H "Accept: application/vnd.github+json" \
  -H "Authorization: Bearer $GITHUB_TOKEN" \
  -H "X-GitHub-Api-Version: 2022-11-28" \
  "$api_url" \
  -d "$json_body" > /dev/null\n\necho "Comment posted to issue #$issue_number: $selected_quote"
